using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "IncreasePurifyReceivedByAllTargetsOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/IncreasePurifyReceivedByAllTargetsOmenData")]
public class IncreasePurifyReceivedByAllTargetsOmenData : OmenData
{
	private const string IncreasePurifyReceivedID = "IncreasePurifyReceived";

	[Header("Increase Purify Received By All Targets")]
	[SerializeField]
	protected int additionalPurifyAmount;

	private Func<int, int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = (int purifyAmount) => purifyAmount + GetAdditionalPurifyAmount();
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnAnyTargetReceivePurifyModifierOmenActions.Add(omenAction);
	}

	protected virtual int GetAdditionalPurifyAmount()
	{
		return additionalPurifyAmount;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Remove(omenAction);
	}

	protected string GetIncreasePurifyReceivedByAllTargetsLocalizedString()
	{
		return GetIncreasePurifyReceivedByAllTargetsLocalizedString(additionalPurifyAmount);
	}

	public string GetIncreasePurifyReceivedByAllTargetsLocalizedString(int externalAdditionalPurifyAmount)
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("IncreasePurifyReceived"), externalAdditionalPurifyAmount);
	}

	public override string OmenConvertedDescription()
	{
		return GetIncreasePurifyReceivedByAllTargetsLocalizedString();
	}
}
